def refine(workshops):
    assert set(OPTIONS)==set(workshops)
    for code,qs in OPTIONS.items():
        for q,replacements in zip(workshops[code]['questions'],qs):
            assert len(replacements)==3 and q['answer'] not in replacements
            for i,s in replacements.items():q['options'][i]=bi(s)
